<script setup lang="ts">
import {onMounted,ref,toRaw,nextTick} from 'vue'
import {technicalDrills,technicalById} from '../domain/technical'
import type {Interview} from '../domain/interview'
import {emptyTechnicalGoals,parseTechnicalGoals,createTechnicalGoal,linkTechnicalGoal,finishTechnicalGoal,unlinkTechnicalGoal,technicalGoalState,type TechnicalGoals,type TechnicalGoal} from '../domain/technical-goals'
import {loadTechnicalGoals,saveTechnicalGoals} from '../technical-goals-storage'
const props=defineProps<{attempts:Interview[]|null;initialGoalId?:string;focus?:boolean}>(),emit=defineEmits<{open:[id:string]}>()
const data=ref(emptyTechnicalGoals()),ready=ref(false),failed=ref(false),busy=ref(false),message=ref(''),questionId=ref(technicalDrills[0]!.id),text=ref(''),target=ref(1),mode=ref<TechnicalGoal['mode']>('ANY'),choices=ref<Record<string,string>>({})
onMounted(async()=>{try{data.value=await loadTechnicalGoals()}catch{failed.value=true;message.value='Không đọc được mục tiêu. Không ghi đè; có thể khôi phục backup hợp lệ.'}finally{ready.value=true;await nextTick();if(props.initialGoalId&&!failed.value){const goal=data.value.goals.find(g=>g.id===props.initialGoalId);if(goal)document.getElementById('technical-goal-'+goal.id)?.scrollIntoView({block:'start'});else message.value='Mục tiêu đã bị xóa hoặc thay thế; hãy chọn mục tiêu hiện có.'}else if(props.focus||props.initialGoalId)document.querySelector('[data-testid=technical-goals]')?.scrollIntoView({block:'start'})}})
async function commit(next:TechnicalGoals){busy.value=true;message.value='';try{await saveTechnicalGoals(next);data.value=next;failed.value=false;message.value='Đã lưu mục tiêu trên thiết bị.'}catch{message.value='Không lưu được mục tiêu; bản đã lưu được giữ nguyên.'}finally{busy.value=false}}
function run(fn:()=>TechnicalGoals){try{void commit(fn())}catch{message.value='Không cập nhật được: kiểm tra mục tiêu mở trùng bài/chế độ, giới hạn 50 mục/20 lượt, nội dung hoặc lượt đã gửi hiện hành.'}}
function link(id:string){const a=props.attempts?.find(a=>a.id===choices.value[id]);if(!a){message.value='Chọn một lượt đã gửi đúng bài.';return}run(()=>linkTechnicalGoal(toRaw(data.value),id,toRaw(a)))}
function remove(id?:string){if(window.confirm(id?'Xóa mục tiêu này? Các lượt Interview vẫn được giữ.':'Xóa toàn bộ mục tiêu? Các lượt Interview vẫn được giữ.'))run(()=>id?{...toRaw(data.value),goals:data.value.goals.filter(g=>g.id!==id).map(g=>toRaw(g))}:emptyTechnicalGoals())}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='brse-technical-goals.json';a.click();URL.revokeObjectURL(url)}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>200000)throw Error();const next=parseTechnicalGoals(await file.text());if(window.confirm('Thay thế toàn bộ mục tiêu kỹ thuật? Dữ liệu Interview giữ nguyên.'))await commit(next)}catch{message.value='Backup mục tiêu không hợp lệ; không thay dữ liệu.'}finally{input.value=''}}
</script>
<template><section class="card form-card" data-testid="technical-goals"><h2>Mục tiêu luyện kỹ thuật</h2><p>Tự đặt mục tiêu, rồi liên kết từng lượt đã gửi đúng bài. Chỉ lượt đúng chế độ của mục tiêu được tính. Số lượt hiện hành không phải điểm kỹ năng; Initial, Guided và Independent được báo riêng. Không tự suy kinh nghiệm từ CV.</p><p v-if="message" role="status">{{message}}</p><p v-if="!ready">Đang đọc mục tiêu…</p><template v-else><form @submit.prevent="run(()=>createTechnicalGoal(toRaw(data),questionId,text,target,Date.now(),mode))"><label>Bài cho mục tiêu<select v-model="questionId" :disabled="busy||failed"><option v-for="q in technicalDrills" :key="q.id" :value="q.id">{{q.title}}</option></select></label><label>Chế độ tính mục tiêu<select v-model="mode" :disabled="busy||failed"><option value="ANY">Tất cả chế độ</option><option value="INITIAL">Initial</option><option value="GUIDED">Guided</option><option value="INDEPENDENT">Independent</option></select></label><label>Mục tiêu do tôi đặt<textarea v-model="text" maxlength="500" :disabled="busy||failed"></textarea></label><label>Số lượt muốn tự luyện<input v-model.number="target" type="number" min="1" max="20" :disabled="busy||failed"></label><button :disabled="busy||failed">Tạo mục tiêu kỹ thuật</button></form><p v-if="failed">N/A · Chưa đọc được mục tiêu.</p><p v-else-if="!data.goals.length">Chưa có mục tiêu kỹ thuật.</p><article v-for="g in data.goals" :key="g.id" :id="'technical-goal-'+g.id" class="notice" :class="{focused:g.id===initialGoalId}"><h3>{{technicalById(g.questionId)?.title}}</h3><p>{{g.text}}</p><p>{{g.status}} · {{g.mode==='ANY'?'Tất cả':g.mode}} · {{technicalGoalState(g,attempts)?.count??'N/A'}} / {{g.target}} lượt hiện hành đúng chế độ</p><template v-if="technicalGoalState(g,attempts)"><p>Initial {{technicalGoalState(g,attempts)!.initial}} · Guided {{technicalGoalState(g,attempts)!.guided}} · Independent {{technicalGoalState(g,attempts)!.independent}}</p><p>{{technicalGoalState(g,attempts)!.excluded}} lượt hiện hành khác chế độ không tính vào mục tiêu.</p><p>{{technicalGoalState(g,attempts)!.missing}} liên kết thiếu · {{technicalGoalState(g,attempts)!.stale}} liên kết lỗi thời</p><p v-if="g.status==='DONE'">{{technicalGoalState(g,attempts)!.met?'Đã tự ghi nhận; liên kết vẫn đủ hiện hành.':'Đã tự ghi nhận trước đây; liên kết không còn đủ hiện hành.'}}</p></template><p v-else>N/A · Chưa đọc được dữ liệu Interview để đối chiếu.</p><form v-if="g.status==='OPEN'" @submit.prevent="link(g.id)"><label>Lượt để liên kết<select v-model="choices[g.id]" :disabled="busy||attempts===null"><option value="">Chọn lượt đã gửi…</option><option v-for="a in (attempts??[]).filter(a=>a.questionId===g.questionId&&a.status==='REVIEWED'&&(g.mode==='ANY'||a.mode===g.mode))" :key="a.id" :value="a.id">{{a.mode}} · {{new Date(a.createdAt).toLocaleString('vi-VN')}} · v{{a.revisions.length}}</option></select></label><button :disabled="busy||attempts===null">Liên kết lượt kỹ thuật</button><button type="button" :disabled="busy||!technicalGoalState(g,attempts)?.met" @click="run(()=>finishTechnicalGoal(toRaw(data),g.id,attempts,Date.now()))">Tự ghi nhận mục tiêu đã luyện</button></form><div v-for="l in g.links" :key="l.attemptId" class="actions"><span>Lượt v{{l.version}}</span><button :disabled="!attempts?.some(a=>a.id===l.attemptId)||busy" @click="emit('open',l.attemptId)">Mở lượt liên kết</button><button v-if="g.status==='OPEN'" :disabled="busy" @click="run(()=>unlinkTechnicalGoal(toRaw(data),g.id,l.attemptId))">Bỏ liên kết lượt</button></div><button :disabled="busy" @click="remove(g.id)">Xóa mục tiêu này</button></article><h3>Backup mục tiêu riêng</h3><p>JSON chưa mã hóa, chỉ chứa mục tiêu và ID/version liên kết. Không chứa transcript hay rubric; cần backup Interview riêng để khôi phục các lượt. Import mục tiêu trước Interview có thể hiển thị liên kết thiếu, không tự tạo transcript.</p><div class="actions"><button :disabled="busy||failed" @click="download">Xuất mục tiêu JSON</button><label class="file-button">Nhập mục tiêu JSON<input type="file" accept="application/json,.json" :disabled="busy" @change="upload"></label><button :disabled="busy||failed" @click="remove()">Xóa toàn bộ mục tiêu</button></div></template></section></template>
<style scoped>textarea{width:100%;min-height:80px;box-sizing:border-box}p{overflow-wrap:anywhere}.focused{outline:2px solid #37795c;scroll-margin-top:24px}</style>
